# Extract formulas and theoretical information from all HTML files
formulas_and_concepts = {}

for file_path in sorted_html_files:
    file_name = os.path.basename(file_path)
    extracted_content = extract_formulas_and_concepts(file_path)
    formulas_and_concepts[file_name] = extracted_content

# Summarize the learned content for review
formulas_and_concepts_summary = {
    file_name: len(content.splitlines()) for file_name, content in formulas_and_concepts.items() if content.strip()
}

formulas_and_concepts_summary

